# AUTO-GENERATED by Claude Code
# Purpose: SmashDb, the master database: the cleaned, normalized tables in the parquet/ folder
#          next to this file (one *.parquet per table), queried with SQL. Only SmashDb's
#          tables go in that folder; a source's own data stays under ds/data/raw/<site>/
#          (spec/pkgs/ds/data/data_storage.md).
# Usage: from ds.data import init_db; init_db().sql("select * from framedata")
# ---------------------------------------------------------------------------
from __future__ import annotations

from pathlib import Path

import polars as pl

from ds.data.paths import PARQUET_DIR

__all__ = ["SmashDb", "init_db"]

# the folder of *.parquet tables (ds.data.paths); kept as DATA_DIR, the name callers import
DATA_DIR = PARQUET_DIR


class SmashDb:
    """The master Smash dataset: cleaned, normalized tables that share one vocabulary.

    Every table speaks this repo's own terms (`char_id`, `char_group`, UTC dates, `{table}_id`
    foreign keys; spec/pkgs/ds/data/external_sources.md), so any two can be joined without
    translating. What is NOT in here: a source's own concepts (a site's character ids, names
    or slugs) and raw or intermediate data. Those are normalized before they are stored, or
    stay inside that source's code under ds/data/raw/<site>/.

    Each *.parquet file in data_dir is a table named by its file name (char.parquet -> `char`):
    smash_db.sql("select * from framedata"). The tables' columns, keys and joins are
    documented in pkgs/ds/data/README.md.
    """

    def __init__(self, data_dir: Path = DATA_DIR) -> None:
        self.data_dir = data_dir
        # one table per *.parquet file, named by its filename stem (eg char.parquet -> "char")
        self._tables = {p.stem: pl.scan_parquet(p) for p in sorted(data_dir.glob("*.parquet"))}
        self._ctx = pl.SQLContext(**self._tables)

    def sql(self, sql: str) -> pl.DataFrame:
        """Run a SQL query against the tables, eg smash_db.sql("select * from framedata")."""
        return self._ctx.execute(sql, eager=True)

    def tables(self) -> list[str]:
        """Table names, read off the live SQL context (not self._tables).

        So tables made/dropped through sql() (eg "create table x as select ...") are included.
        """
        return self._ctx.tables()

    def table_schema(self, table: str) -> pl.Schema:
        """{column: dtype} for one table.

        Lazy, so for a parquet table this only reads the file footer's metadata, not any rows.
        """
        return self._ctx.execute(f'SELECT * FROM "{table}"').collect_schema()

    def schema(self) -> dict[str, pl.Schema]:
        """{table: {column: dtype}} for every table, eg smash_db.schema()["char"]"""
        return {table: self.table_schema(table) for table in self.tables()}


def init_db() -> SmashDb:
    """SmashDb over its own tables (pkgs/ds/data/smash_db/parquet)."""
    return SmashDb()
